// Cloudflare Workers - ES Module Format + D1 API
const FILES = {
  '/index.html':``,
  '/admin.html':``,
  '/category.html':``,
  '/favorites.html':``,
  '/import-export.html':``,
  '/tool.html':``,
  '/sitemap.html':``,
  '/feedback.html':``,
  '/about.html':``,
  '/manifest.json':``,
  '/robots.txt':``,

  // ==================== IndexNow API Key ====================
  // Bing IndexNow 要求：在根目录托管 API Key 文件
  // 格式：{SHA256_HASH}.txt，文件内容是原始随机字符串
  // 生成方式：random_str = secrets.token_hex(32), api_key = sha256(random_str).hexdigest()
  '/1248516db6dc3f79ba386d685af282ab10120622798ddb374352be839627317b.txt':`N2EwNmZkNzE2NDJlZWE5ZGI1ZjI2OTY5ZmYyZWNjN2Y3MTZkY2M3OC04NDk5Y2VlMjcwMDc3YTM1MTcxNDdkYTQ3NmQ=`,
  '/sitemap.xml':``,
  '/og-image.svg':``,
  '/sw.js':``,
  '/css/style.css':``,
  '/css/ai-badges.css':``,
  '/css/feedback.css':``,
  '/css/favorites.css':``,
  '/js/feedback.js':``,
  '/js/app.js':``,
  '/js/favorites-sync.js':``,
  '/js/analytics.js':``,
  '/js/favorites.js':``,
  '/data/.baidu_push_state.json':``,
  '/data/.indexnow_key.txt':`1248516db6dc3f79ba386d685af282ab10120622798ddb374352be839627317b`,
  '/data/tools.json':``
};

export default {
  async fetch(request, env, ctx) {
    const u = new URL(request.url);
    const p = u.pathname;
    
    // ==================== API 路由 ====================
    
    // POST /api/feedback - 提交反馈
    if (p === '/api/feedback' && request.method === 'POST') {
      try {
        const data = await request.json();
        const { feedback_type, tool_id, tool_name, email, content } = data;
        
        if (!content || content.trim().length < 2) {
          return new Response(JSON.stringify({ success: false, error: '内容至少 2 个字符' }), { status: 400 });
        }
        
        // 插入 D1 数据库
        const stmt = env.yingjideng_db.prepare(
          'INSERT INTO feedback (tool_id, tool_name, email, content, status, created_at) VALUES (?, ?, ?, ?, ?, ?)'
        );
        const bind = stmt.bind(tool_id || '', tool_name || '', email || '', content.trim(), 'pending', new Date().toISOString());
        await bind.run();
        
        // 邮件通知（异步）
        if (env.RESEND_API_KEY && content.length > 0) {
          try {
            await env.RESEND_API_KEY.fetch('https://api.resend.com/emails', {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${env.RESEND_API_KEY}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({
                from: env.SMTP_FROM || 'yingjideng@resend.dev',
                to: [env.NOTIFY_TO || env.SMTP_FROM],
                subject: `📩 新反馈 - ${tool_name || '未指定工具'}`,
                html: `<h3>新反馈</h3><p><strong>工具:</strong> ${tool_name || '未指定'}</p><p><strong>类型:</strong> ${feedback_type || '未指定'}</p><p><strong>邮箱:</strong> ${email || '未提供'}</p><p><strong>内容:</strong><br/>${content.replace(/\n/g, '<br/>')}</p><p><em>时间: ${new Date().toLocaleString('zh-CN')}</em></p>`
              })
            });
          } catch (e) {
            console.error('Email notification failed:', e);
          }
        }
        
        return new Response(JSON.stringify({ success: true, message: '提交成功，我们会尽快处理' }), {
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 400 });
      }
    }
    
    // GET /api/reviews/:toolId - 获取工具评价
    if (p.startsWith('/api/reviews/') && request.method === 'GET') {
      try {
        const toolId = p.replace('/api/reviews/', '');
        if (!toolId) {
          return new Response(JSON.stringify({ success: false, error: '缺少 toolId' }), { status: 400 });
        }
        
        const stmt = env.yingjideng_db.prepare(
          'SELECT * FROM reviews WHERE tool_id = ? ORDER BY created_at DESC'
        );
        const bind = stmt.bind(toolId);
        const { results } = await bind.all();
        
        return new Response(JSON.stringify({ success: true, reviews: results || [] }), {
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 });
      }
    }
    
    // POST /api/reviews - 提交评价
    if (p === '/api/reviews' && request.method === 'POST') {
      try {
        const data = await request.json();
        const { tool_id, tool_name, rating, comment, author } = data;
        
        if (!tool_id || !rating || rating < 1 || rating > 5) {
          return new Response(JSON.stringify({ success: false, error: '缺少 tool_id 或 rating(1-5)' }), { status: 400 });
        }
        
        const stmt = env.yingjideng_db.prepare(
          'INSERT INTO reviews (tool_id, tool_name, rating, comment, author, created_at) VALUES (?, ?, ?, ?, ?, ?)'
        );
        const bind = stmt.bind(tool_id, tool_name || '', rating, comment || '', author || '匿名', new Date().toISOString());
        await bind.run();
        
        return new Response(JSON.stringify({ success: true, message: '评价已提交' }), {
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 400 });
      }
    }
    
    // GET /api/favorites - 获取用户收藏
    if (p === '/api/favorites' && request.method === 'GET') {
      try {
        const userId = u.searchParams.get('user_id') || '';
        if (!userId) {
          return new Response(JSON.stringify({ success: false, error: '缺少 user_id' }), { status: 400 });
        }
        
        const stmt = env.yingjideng_db.prepare(
          'SELECT * FROM favorites WHERE user_id = ? ORDER BY created_at DESC'
        );
        const bind = stmt.bind(userId);
        const { results } = await bind.all();
        
        return new Response(JSON.stringify({ success: true, favorites: results || [] }), {
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 500 });
      }
    }
    
    // POST /api/favorites - 添加/删除收藏
    if (p === '/api/favorites' && request.method === 'POST') {
      try {
        const data = await request.json();
        const { user_id, action, tool_id, tool_name } = data;
        
        if (!user_id || !tool_id) {
          return new Response(JSON.stringify({ success: false, error: '缺少 user_id 或 tool_id' }), { status: 400 });
        }
        
        if (action === 'add') {
          const stmt = env.yingjideng_db.prepare(
            'INSERT OR REPLACE INTO favorites (user_id, tool_id, tool_name, created_at) VALUES (?, ?, ?, ?)'
          );
          const bind = stmt.bind(user_id, tool_id, tool_name || '', new Date().toISOString());
          await bind.run();
        } else if (action === 'remove') {
          const stmt = env.yingjideng_db.prepare(
            'DELETE FROM favorites WHERE user_id = ? AND tool_id = ?'
          );
          const bind = stmt.bind(user_id, tool_id);
          await bind.run();
        }
        
        return new Response(JSON.stringify({ success: true }), {
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 400 });
      }
    }
    
    // ==================== IndexNow API ====================
    
    const INDEXNOW_API_KEY = '1248516db6dc3f79ba386d685af282ab10120622798ddb374352be839627317b';
    const INDEXNOW_KEY_FILE = `${INDEXNOW_API_KEY}.txt`;
    
    // GET /indexnow - 返回 API Key 内容（IndexNow 协议端点）
    if (p === '/indexnow' && request.method === 'GET') {
      return new Response(INDEXNOW_API_KEY, {
        headers: { 'Content-Type': 'text/plain' }
      });
    }
    
    // GET /{API_KEY}.txt - 返回 API Key 内容（Bing 验证文件）
    if (p === `/${INDEXNOW_KEY_FILE}` && request.method === 'GET') {
      return new Response(INDEXNOW_API_KEY, {
        headers: { 'Content-Type': 'text/plain' }
      });
    }
    
    // POST /indexnow - 接收 IndexNow 提交
    if (p === '/indexnow' && request.method === 'POST') {
      try {
        const data = await request.json();
        // IndexNow 协议使用 urlList（驼峰），但也支持 url_list（兼容）
        const { host, key, urlList, url_list } = data;
        const urls = urlList || url_list;
        
        // 验证 API Key
        if (key !== '1248516db6dc3f79ba386d685af282ab10120622798ddb374352be839627317b') {
          return new Response(JSON.stringify({ success: false, error: 'Invalid API Key' }), { status: 403 });
        }
        
        // 验证 host
        if (host !== 'yingjideng.dpdns.org') {
          return new Response(JSON.stringify({ success: false, error: 'Invalid host' }), { status: 403 });
        }
        
        // 验证 url_list
        if (!Array.isArray(urls) || urls.length === 0) {
          return new Response(JSON.stringify({ success: false, error: 'Missing urlList or url_list' }), { status: 400 });
        }
        
        // 记录提交的 URL（可选：存入数据库）
        console.log(`[IndexNow] Submitted ${urls.length} URLs:`, urls.slice(0, 5));
        
        return new Response(JSON.stringify({ success: true }), { status: 200 });
      } catch (e) {
        return new Response(JSON.stringify({ success: false, error: e.message }), { status: 400 });
      }
    }
    
    // ==================== 静态文件服务 ====================
    
    let pathname = p;
    if (pathname === '/' || pathname === '/index.html') pathname = '/index.html';
    if (pathname.endsWith('/') && pathname !== '/') pathname = pathname.slice(0, -1);
    
    // 工具详情页路由：/tool/{toolId} → tool.html，动态替换 canonical 和 OG 标签
    const toolMatch = pathname.match(/^\/tool\/(.+)$/);
    if (toolMatch) {
      const toolId = toolMatch[1];
      const fullUrl = `${u.protocol}//${u.host}/tool/${toolId}`;
      let content = FILES['/tool.html'];
      
      // 动态替换 canonical URL
      content = content.replace(
        /<link rel="canonical" id="canonical-url" href="[^"]*">/,
        `<link rel="canonical" id="canonical-url" href="${fullUrl}">`
      );
      
      // 动态替换 OG URL
      content = content.replace(
        /<meta property="og:url" id="tool-og-url" content="[^"]*">/,
        `<meta property="og:url" id="tool-og-url" content="${fullUrl}">`
      );
      
      // 动态替换 Twitter URL
      content = content.replace(
        /<meta name="twitter:url" id="tool-tw-url" content="[^"]*">/,
        `<meta name="twitter:url" id="tool-tw-url" content="${fullUrl}">`
      );
      
      return new Response(content, {
        headers: {
          'Content-Type': 'text/html',
          'Cache-Control': 'public, max-age=3600'
        }
      });
    }
    
    let content = FILES[pathname] || FILES['/index.html'];
    let contentType = 'text/html';
    
    if (pathname.endsWith('.css')) contentType = 'text/css';
    else if (pathname.endsWith('.js')) contentType = 'application/javascript';
    else if (pathname.endsWith('.json')) contentType = 'application/json';
    else if (pathname.endsWith('.svg')) contentType = 'image/svg+xml';
    else if (pathname.endsWith('.xml')) contentType = 'application/xml';
    else if (pathname.endsWith('.ico')) contentType = 'image/x-icon';
    else if (pathname.endsWith('.png')) contentType = 'image/png';
    else if (pathname.endsWith('.jpg') || pathname.endsWith('.jpeg')) contentType = 'image/jpeg';
    else if (pathname.endsWith('.gif')) contentType = 'image/gif';
    else if (pathname.endsWith('.woff2')) contentType = 'font/woff2';
    else if (pathname.endsWith('.woff')) contentType = 'font/woff';
    else if (pathname.endsWith('.ttf')) contentType = 'font/ttf';
    else if (pathname.endsWith('.otf')) contentType = 'font/otf';
    
    // 将 base64 解码为 Uint8Array 以正确处理 UTF-8
    let binary = atob(content);
    let bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    
    return new Response(bytes, {
      headers: {
        'Content-Type': contentType,
        'Cache-Control': 'public, max-age=3600'
      }
    });
  }
};
